pub(crate) fn ct_count_page(gl: &mut crate::port::Cells, page: i32) -> i32 {
    let n: i32 = gl_count(gl);
    let mut g: i32 = 0;
    let mut c: i32 = 0;
    while g < n {
        if gl_get(gl, g, ch_page()) == page {
            c += 1;
        }
        g += 1;
    }
    return c;
}
pub(crate) fn ct_real_rows(emon_t: i32, rows: &[u8]) -> i32 {
    // real.txt: `path page digest glyphs`. The file is one of corpus/ (not committed):
    // the digest of the page's glyph stream and its glyph count are what emon made of it
    // when pdfminer.six agreed, and must not change.
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let dc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let b: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cx: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ox: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f0: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f1: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f2: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f3: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mk: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fnt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let n: i32 = crate::port::blob_len(rows);
    let mut pos: i32 = 0;
    let mut line: i32 = 0;
    let mut e: i32 = 0;
    let mut t1: i32 = 0;
    let mut t2: i32 = 0;
    let mut t3: i32 = 0;
    let mut page: i32 = 0;
    let mut rowsn: i32 = 0;
    while pos < n {
        line += 1;
        e = ct_nl(rows, pos);
        if (pos < e) && (crate::port::blob_u8(rows, pos) != 35) {
            t1 = ct_tab(rows, pos, e);
            t2 = ct_tab(rows, t1 + 1, e);
            t3 = ct_tab(rows, t2 + 1, e);
            page = ct_dec(rows, t1 + 1, t2);
            rowsn += 1;
            crate::testport::assert_eq_at(ct_run(&crate::port::src_of_blob(&crate::testport::test_file_span(rows, pos, t1)[..]), ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln), 0, "the file ran", line);
            crate::testport::assert_eq_at(cr_digest(gl, et, page), ct_dec(rows, t2 + 1, t3), "digest of the page's text", line);
            crate::testport::assert_eq_at(ct_count_page(gl, page), ct_dec(rows, t3 + 1, e), "glyphs on the page", line);
        }
        pos = e + 1;
    }
    return rowsn;
}
#[test]
fn test_real_files_make_the_glyph_streams_pdfminer_agreed_with() {
    crate::testport::assert_that(ct_real_rows(0, &crate::testport::test_file("content/real.txt")[..]) > 100, "the real rows were read");
}
pub(crate) fn ct_copy(b: &[u8], mut c: &mut crate::port::Cells) -> i32 {
    let n: i32 = crate::port::blob_len(b);
    let mut i: i32 = 0;
    crate::port::cells_drop(c, 0);
    while i < n {
        crate::port::cells_push(c, crate::port::blob_u8(b, i));
        i += 1;
    }
    return n;
}
pub(crate) fn ct_fuzz_file(emon_t: i32, bytes: &[u8], iters: i32, cut_step: i32) -> i32 {
    // Flip 1-6 random bytes `iters` times, and cut the file at every `cut-step` bytes; run each.
    // Nothing is asserted but that no run faults, on any target, whatever it says.
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let dc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let b: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cx: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ox: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f0: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f1: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f2: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f3: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mk: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fnt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let work: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rng: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let n: i32 = crate::port::blob_len(bytes);
    let mut it: i32 = 0;
    let mut k: i32 = 0;
    let mut flips: i32 = 0;
    let mut cut: i32 = 0;
    let mut runs: i32 = 0;
    let mut at: i32 = 0;
    sm_seed(rng, 4242);
    while it < iters {
        ct_copy(bytes, work);
        flips = 1 + sm_below(rng, 6);
        k = 0;
        while k < flips {
            at = sm_below(rng, n);
            crate::port::cells_set(work, at, sm_below(rng, 256));
            k += 1;
        }
        ct_run(&crate::port::src_of_cells(work), ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln);
        runs += 1;
        it += 1;
    }
    cut = cut_step;
    while cut < n {
        ct_copy(bytes, work);
        crate::port::cells_drop(work, cut);
        ct_run(&crate::port::src_of_cells(work), ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln);
        runs += 1;
        cut += cut_step;
    }
    return runs;
}
#[test]
fn test_corrupted_and_cut_files_never_fault() {
    crate::testport::assert_that(ct_fuzz_file(0, &crate::testport::test_file("content/ops.pdf")[..], 300, 29) > 300, "ops.pdf");
    crate::testport::assert_that(ct_fuzz_file(0, &crate::testport::test_file("content/marked.pdf")[..], 300, 31) > 300, "marked.pdf");
    crate::testport::assert_that(ct_fuzz_file(0, &crate::testport::test_file("content/forms.pdf")[..], 300, 29) > 300, "forms.pdf");
    crate::testport::assert_that(ct_fuzz_file(0, &crate::testport::test_file("content/fonts.pdf")[..], 300, 37) > 300, "fonts.pdf");
    crate::testport::assert_that(ct_fuzz_file(0, &crate::testport::test_file("content/damaged.pdf")[..], 300, 29) > 300, "damaged.pdf");
    crate::testport::assert_that(ct_fuzz_file(0, &crate::testport::test_file("pdf/html-chrome.pdf")[..], 100, 401) > 100, "a Chrome file");
}
